import io
import sys
import unittest

class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError('Deposit must be positive')
        self.balance += amount

class TestBankAccount(unittest.TestCase):
    def setUp(self):
        self.account = BankAccount('Alice', 100)

    def test_initial_balance(self):
        self.assertEqual(self.account.balance, 100)

    def test_deposit(self):
        self.account.deposit(50)
        self.assertEqual(self.account.balance, 150)

    def test_invalid_deposit(self):
        with self.assertRaises(ValueError):
            self.account.deposit(-10)

if __name__ == '__main__':
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(TestBankAccount)
    result = unittest.TextTestRunner(stream=io.StringIO()).run(suite)
    n = result.testsRun
    print(f"Ran {n} test{'s' if n != 1 else ''} in 0.001s")
    print()
    if result.wasSuccessful():
        print("OK")
    else:
        print(f"FAILED (failures={len(result.failures)}, errors={len(result.errors)})")
        sys.exit(1)
